import React, { useState } from "react";
import axios from "axios";

interface SimplifiedResult {
  simplified_explanation: string;
  steps: string[];
  analogy: { text: string; mapping: Array<{ concept: string; analogy: string }> };
  why_explanation: string;
}

interface VerificationResult {
  results: Array<{ claim: string; status: string; evidence: string; confidence: number }>;
  support_score: number;
}

interface QuizQuestion {
  question: string;
  options: string[];
  answer: string;
}

interface FullResult {
  simplified: SimplifiedResult;
  verification: VerificationResult;
  quiz: { questions: QuizQuestion[] };
}

function App() {
  const [text, setText] = useState<string>("");
  const [result, setResult] = useState<FullResult | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [showResults, setShowResults] = useState<boolean>(false);

  const processText = async () => {
    if (!text.trim()) return alert("Please enter some text");
    setLoading(true);
    setSelectedAnswers({});
    setShowResults(false);

    try {
      const res = await axios.post("http://localhost:5000/process", { text });
      setResult(res.data);
    } catch (err: any) {
      alert("Error: " + (err.response?.data?.error || err.message));
    } finally {
      setLoading(false);
    }
  };

  const handleAnswerSelect = (questionIndex: number, selectedOption: string) => {
    setSelectedAnswers(prev => ({
      ...prev,
      [questionIndex]: selectedOption
    }));
  };

  const checkAnswers = () => {
    setShowResults(true);
  };

  return (
    <div style={{ padding: "30px", maxWidth: "1100px", margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", color: "#1e3a8a" }}>🧠 Feynman AI System</h1>

      <textarea
        rows={8}
        style={{ width: "100%", padding: "15px", fontSize: "16px", borderRadius: "8px", border: "1px solid #ccc" }}
        placeholder="Paste your academic text here..."
        value={text}
        onChange={(e) => setText(e.target.value)}
      />

      <br /><br />
      <button
        onClick={processText}
        disabled={loading}
        style={{
          padding: "15px 40px",
          fontSize: "18px",
          background: "#1e3a8a",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: loading ? "not-allowed" : "pointer"
        }}
      >
        {loading ? "Processing... (may take 10-20s)" : "🚀 Simplify + Verify + Quiz"}
      </button>

      {result && (
        <div style={{ marginTop: "40px" }}>
          {/* Simplified Explanation */}
          <h2>✅ Simplified Explanation</h2>
          <p style={{ fontSize: "18px", lineHeight: "1.6" }}>{result.simplified.simplified_explanation}</p>

          <h3>Steps</h3>
          <ol>
            {result.simplified.steps.map((step, i) => (
              <li key={i} style={{ fontSize: "17px", marginBottom: "8px" }}>{step}</li>
            ))}
          </ol>

          <h3>Analogy</h3>
          <p><strong>{result.simplified.analogy.text}</strong></p>
          <ul>
            {result.simplified.analogy.mapping.map((m, i) => (
              <li key={i}><strong>{m.concept}</strong> → {m.analogy}</li>
            ))}
          </ul>

          <h3>Why it works</h3>
          <p>{result.simplified.why_explanation}</p>

          {/* Verification */}
          <h2>🔍 Verification Results</h2>
          <h3>Support Score: <span style={{ color: result.verification.support_score >= 80 ? "green" : "red", fontWeight: "bold" }}>
            {result.verification.support_score}%
          </span></h3>

          <table style={{ width: "100%", borderCollapse: "collapse", marginTop: "15px" }}>
            <thead>
              <tr style={{ background: "#f1f5f9" }}>
                <th style={{ padding: "12px", textAlign: "left" }}>Claim</th>
                <th style={{ padding: "12px", textAlign: "left" }}>Status</th>
                <th style={{ padding: "12px", textAlign: "left" }}>Evidence</th>
              </tr>
            </thead>
            <tbody>
              {result.verification.results.map((r, i) => (
                <tr key={i} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ padding: "12px" }}>{r.claim}</td>
                  <td style={{ padding: "12px", fontWeight: "bold",
                    color: r.status === "SUPPORTED" ? "green" : r.status === "CONTRADICTED" ? "red" : "orange" }}>
                    {r.status}
                  </td>
                  <td style={{ padding: "12px", fontStyle: "italic" }}>{r.evidence}</td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* Improved Interactive Quiz */}
<h2>📝 Quiz (4 Questions)</h2>
<p style={{ color: "#555", marginBottom: "20px" }}>
  Select your answer for each question then click "Check Answers"
</p>

{result.quiz.questions.map((q, index) => {
  const userAnswer = selectedAnswers[index];
  const correctAnswer = q.answer;                    // This is "A", "B", "C", or "D"
  const hasAnswered = userAnswer !== undefined;
  const isCorrect = userAnswer === correctAnswer;    // Compare only letter (A/B/C/D)

  return (
    <div key={index} style={{
      marginBottom: "35px",
      padding: "20px",
      border: "1px solid #ddd",
      borderRadius: "10px",
      background: "#f8fafc"
    }}>
      <p style={{ fontWeight: "bold", fontSize: "17px", marginBottom: "15px" }}>
        {index + 1}. {q.question}
      </p>

      <div style={{ marginTop: "12px" }}>
        {q.options.map((option, i) => {
          // Extract just the letter (A, B, C, D) from the option
          const optionLetter = option.charAt(0);   // "A", "B", etc.

          const isSelected = userAnswer === optionLetter;
          const isRightAnswer = optionLetter === correctAnswer;

          let bgColor = "#f1f5f9";
          if (showResults) {
            if (isRightAnswer) bgColor = "#d4edda";      // Green for correct
            else if (isSelected) bgColor = "#f8d7da";    // Red for wrong selection
          } else if (isSelected) {
            bgColor = "#cce5ff";                         // Blue when selected
          }

          return (
            <div
              key={i}
              onClick={() => !showResults && handleAnswerSelect(index, optionLetter)}
              style={{
                padding: "14px 16px",
                margin: "8px 0",
                borderRadius: "8px",
                backgroundColor: bgColor,
                cursor: showResults ? "default" : "pointer",
                border: isSelected ? "2px solid #1e3a8a" : "1px solid #ccc",
                fontSize: "16px",
                transition: "all 0.2s"
              }}
            >
              {option}
              {showResults && isRightAnswer && (
                <span style={{ float: "right", color: "green", fontWeight: "bold" }}>✓ Correct</span>
              )}
              {showResults && isSelected && !isRightAnswer && (
                <span style={{ float: "right", color: "red", fontWeight: "bold" }}>✕ Wrong</span>
              )}
            </div>
          );
        })}
      </div>

      {showResults && !isCorrect && (
        <p style={{ color: "red", marginTop: "10px" }}>
          Correct answer is: <strong>{correctAnswer}</strong>
        </p>
      )}
    </div>
  );
})}

{/* Check Answers Button */}
{!showResults && Object.keys(selectedAnswers).length > 0 && (
  <button
    onClick={checkAnswers}
    style={{
      padding: "14px 32px",
      fontSize: "17px",
      background: "#28a745",
      color: "white",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      marginTop: "20px"
    }}
  >
    Check Answers
  </button>
)}

{showResults && (
  <button
    onClick={() => {
      setShowResults(false);
      setSelectedAnswers({});
    }}
    style={{
      padding: "14px 32px",
      fontSize: "17px",
      background: "#6c757d",
      color: "white",
      border: "none",
      borderRadius: "8px",
      cursor: "pointer",
      marginTop: "20px"
    }}
  >
    Try Quiz Again
  </button>
)}
        </div>
      )}
    </div>
  );
}

export default App;
